import assert from "node:assert/strict";
import { existsSync } from "node:fs";
import { mkdir, mkdtemp, readFile, rm } from "node:fs/promises";
import { resolve } from "node:path";
import { after, test } from "node:test";
import { pathToFileURL } from "node:url";

import { build } from "rolldown";

// src/ReadComicsOnline/ and src/utils/mmrcms/ are generated by `npm run sync:comics`.
const synced = existsSync("src/ReadComicsOnline/main.ts");
const BASE = "https://readcomicsonline.ru";
const CDN = "https://cdn.readcomicsonline.ru/uploads/manga";
// Pages captured on 27 October 2026 from the live site (raw server HTML).
const fixture = (name) => readFile(`fixtures/readcomicsonline/${name}-2026-10.html`);

const requests = [];
let source;
if (synced) {
  await mkdir("node_modules/.cache", { recursive: true });
  const directory = await mkdtemp(resolve("node_modules/.cache/tascabile-rco-"));
  after(() => rm(directory, { recursive: true, force: true }));
  await build({
    input: { rco: "src/ReadComicsOnline/main.ts" },
    external: ["@paperback/types", "cheerio", "htmlparser2"],
    output: { dir: directory, format: "esm", entryFileNames: "[name].mjs" },
  });

  const routes = {
    [`${BASE}/comic-list?sort=views&page=1`]: "list-views",
    [`${BASE}/comic-list?sort=views&page=5`]: "list-views-5",
    [`${BASE}/advanced-search?name=batman&page=1`]: "search-batman",
    [`${BASE}/advanced-search?name=zzqxnotacomic&page=1`]: "search-none",
    [`${BASE}/comic/absolute-batman-2024`]: "detail-absolute-batman-2024",
    [`${BASE}/comic/batman-2016`]: "detail-batman-2016",
    [`${BASE}/comic/absolute-batman-2024/1`]: "reader-absolute-batman-2024-1",
  };
  const state = new Map();
  globalThis.Application = {
    getState: (key) => state.get(key),
    setState: (value, key) => state.set(key, value),
    getDefaultUserAgent: async () => "test",
    arrayBufferToUTF8String: (data) => Buffer.from(data).toString("utf8"),
    Selector: (target, method) => ({ target, method }),
    async scheduleRequest(request) {
      requests.push(request);
      const name = request.method === "GET" ? routes[request.url] : undefined;
      if (!name) return [{ status: 404, headers: {}, url: request.url }, new ArrayBuffer(0)];
      const body = await fixture(name);
      const data = body.buffer.slice(body.byteOffset, body.byteOffset + body.byteLength);
      return [{ status: 200, headers: { "content-type": "text/html" }, url: request.url }, data];
    },
  };
  ({ ReadComicsOnline: source } = await import(pathToFileURL(`${directory}/rco.mjs`).href));
}

const rcoTest = (name, fn) => test(name, { skip: !synced && "run npm run sync:comics" }, fn);

await rcoTest("Most Viewed reads the comic list with CDN covers", async () => {
  const { items } = await source.getDiscoverSectionItems({ id: "popular_section" }, undefined);
  assert.equal(items.length, 60);
  assert.deepEqual(
    { id: items[0].mangaId, title: items[0].title, type: items[0].type },
    {
      id: "/comic/absolute-batman-2024",
      title: "Absolute Batman (2024-)",
      type: "featuredCarouselItem",
    },
  );
  assert.ok(items.every((item) => item.imageUrl.startsWith(`${CDN}/`)));
});

await rcoTest("browsing continues past page 5 and decodes double-encoded titles", async () => {
  const { items, metadata } = await source.getSearchResults(
    { title: "" },
    { page: 5, collectedIds: [] },
    { id: "views" },
  );
  assert.equal(items.length, 60);
  // The site serves "Tangle &amp;amp; Whisper".
  assert.ok(items.some((item) => item.title === "Sonic the Hedgehog: Tangle & Whisper (2019-)"));
  assert.equal(metadata.page, 6);
  // Only this page's IDs are carried forward.
  assert.equal(metadata.collectedIds.length, 60);
});

await rcoTest(
  "title search uses the paginated site search, not the 8-item autocomplete",
  async () => {
    const { items, metadata } = await source.getSearchResults({ title: "batman" }, undefined);
    assert.equal(requests.at(-1).url, `${BASE}/advanced-search?name=batman&page=1`);
    assert.equal(items.length, 60);
    assert.deepEqual(
      { id: items[0].mangaId, title: items[0].title },
      { id: "/comic/absolute-batman-2024", title: "Absolute Batman (2024-)" },
    );
    assert.ok(items.some((item) => item.title === "Batman Black & White (2020-)"));
    assert.ok(items.every((item) => item.imageUrl.startsWith(`${CDN}/`)));
    assert.equal(metadata.page, 2);

    const none = await source.getSearchResults({ title: "zzqxnotacomic" }, undefined);
    assert.deepEqual(none, { items: [], metadata: undefined });
  },
);

await rcoTest("details: synopsis, status, category and author", async () => {
  const absolute = (await source.getMangaDetails("/comic/absolute-batman-2024")).mangaInfo;
  assert.equal(absolute.primaryTitle, "Absolute Batman (2024-)");
  assert.match(absolute.synopsis, /^BATMAN LEGEND SCOTT SNYDER/u);
  assert.equal(absolute.status, "Ongoing");
  assert.equal(absolute.author, undefined);
  assert.equal(
    absolute.thumbnailUrl,
    `${CDN}/absolute-batman-2024/cover/cover_250x350.jpg?v=1757155520`,
  );
  assert.deepEqual(
    absolute.tagGroups[0].tags.map((tag) => tag.title),
    ["DC Comics"],
  );
  const batman = (await source.getMangaDetails("/comic/batman-2016")).mangaInfo;
  assert.equal(batman.author, "Tom King");
  assert.match(batman.synopsis, /^"I AM GOTHAM"/u);
});

await rcoTest("chapters: issue numbers from the slug, annuals and specials at 0", async () => {
  const chapters = await source.getChapters({ mangaId: "/comic/absolute-batman-2024" });
  assert.equal(chapters.length, 26);
  const byId = (id) =>
    chapters.find((chapter) => chapter.chapterId === `/comic/absolute-batman-2024/${id}`);
  const view = (chapter) => ({ num: chapter.chapNum, title: chapter.title });
  assert.deepEqual(view(byId("annual2025")), { num: 0, title: "Annual 2025" });
  assert.deepEqual(view(byId("24")), { num: 24, title: "" });
  assert.deepEqual(view(byId("1.1")), { num: 1.1, title: "Noir Edition" });
  const first = byId("1").publishDate;
  assert.deepEqual([first.getFullYear(), first.getMonth(), first.getDate()], [2024, 9, 9]);

  // Batman (2016-): "#Annual 5" used to become issue 5, "#Annual 2022" issue 2022.
  const batman = await source.getChapters({ mangaId: "/comic/batman-2016" });
  const issues = batman.filter((chapter) => chapter.chapNum > 0).map((chapter) => chapter.chapNum);
  assert.equal(new Set(issues).size, issues.length);
  assert.ok(Math.max(...issues) < 1000);
  const annuals = batman.filter((chapter) => chapter.chapNum === 0).map((chapter) => chapter.title);
  assert.ok(annuals.includes("Annual 5") && annuals.includes("Annual 2022"));
});

await rcoTest("reader lists every page in order from the CDN", async () => {
  const details = await source.getChapterDetails({
    chapterId: "/comic/absolute-batman-2024/1",
    sourceManga: { mangaId: "/comic/absolute-batman-2024" },
  });
  assert.equal(details.pages.length, 45);
  assert.equal(details.pages[0], `${CDN}/absolute-batman-2024/chapters/1/01.jpg`);
  assert.ok(
    details.pages.every((url) => url.startsWith(`${CDN}/absolute-batman-2024/chapters/1/`)),
  );
});
